window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5143caa57a238996"]={"versions": [{"id": "FIG-5143caa57a238996", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-Metamodell-Struktur für Sammlungen (<code>Collection</code>) und Instanzreferenzen (<code>AnyInstanceRef</code>) im Rahmen des Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert die Klassenstruktur zur logischen Gruppierung von Modellelementen:</p>\n<ul class=\"fig-list\"><li><code>Identifiable</code> (spezialisiert <code>MultilanguageReferrable</code>): Basisklasse mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.\n</li><li><code>CollectableElement</code> (abstrakt): Spezialisiert <code>Identifiable</code>. Dient als Oberklasse für sammelbare Entitäten.\n</li><li><code>PackageableElement</code> (abstrakt): Spezialisiert <code>CollectableElement</code> und <code>Identifiable</code>.\n</li><li><code>ARPackage</code>: Spezialisiert <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Enthält über die Komposition <code>+element 0..*</code> mit Stereotyp <code>«atpSplitable,atpVariation»</code> Elemente des Typs <code>PackageableElement</code>.\n</li><li><code>ARElement</code> (abstrakt): Spezialisiert <code>PackageableElement</code>.\n</li><li><code>Collection</code>: Spezialisiert <code>ARElement</code>. Besitzt die Attribute <code>autoCollect: AutoCollectEnum [0..1]</code> und <code>elementRole: Identifier [0..1]</code>. Assoziiert direkt sammelbare Elemente über <code>+element 0..*</code> zu <code>Identifiable</code> sowie Quellelemente über <code>+sourceElement 0..*</code> zu <code>Identifiable</code>.\n</li><li><code>AutoCollectEnum</code> («enumeration»): Werte <code>refAll</code>, <code>refNonStandard</code>, <code>refNone</code>.\n</li><li><code>AtpFeature</code>: Basisklasse für referenzierbare Features.\n</li><li><code>AtpInstanceRef</code> / <code>AnyInstanceRef</code>: Modellierung generischer Instanzpfade. Besitzt die Referenzen <code>+target: AtpFeature [1]</code> mit <code>{redefines atpTarget}</code> und <code>+contextElement: AtpFeature [0..*]</code> mit <code>{subsets atpContextElement}</code>.\n</li><li>Kompositionen von <code>Collection</code> zu <code>AnyInstanceRef</code>:\n<ul class=\"fig-list\"><li><code>+collectedInstance 0..*</code> (Instanzreferenz-Spezifikation <code>«instanceRef» +collectedInstance 0..*</code> auf <code>AtpFeature</code>)\n</li><li><code>+sourceInstance 0..*</code> (Instanzreferenz-Spezifikation <code>«instanceRef» +sourceInstance 0..*</code> auf <code>AtpFeature</code>)\n</li></ul>\n</li><li><code>EvaluatedVariantSet</code>: Spezialisiert <code>ARElement</code> mit Attribut <code>approvalStatus: NameToken</code>. Assoziiert ausgewertete Elemente über <code>+evaluatedElement 0..*</code> zu <code>CollectableElement</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen oder Zustandsübergänge. Die Beziehungen definieren die Deklarationshierarchie sowie Mechanismen zur Auflösung von Instanzreferenzen über Kontextelemente hinweg zum Zielobjekt (<code>target</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Collection</code> erlaubt sowohl die direkte Adressierung von Metamodellelementen (<code>Identifiable</code>) über <code>element</code> und <code>sourceElement</code> als auch die instanzbasierte Adressierung über <code>AnyInstanceRef</code> (<code>collectedInstance</code>, <code>sourceInstance</code>).\n</li><li>Bei Verwendung von <code>AnyInstanceRef</code> muss genau ein Ziel (<code>target: 1</code>) referenziert werden; hierarchische Kontexte werden über <code>contextElement [0..*]</code> aufgespannt.\n</li><li>Das Attribut <code>autoCollect</code> steuert automatische Einschlussmechanismen über die Aufzählungswerte von <code>AutoCollectEnum</code>.\n</li><li>Die Assoziation <code>ARPackage.element</code> unterliegt den Mechanismen von Variabilität und Aufspaltbarkeit (<code>«atpSplitable,atpVariation»</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d401b1d18f6322b8", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-Metamodell-Struktur für Sammlungen (<code>Collection</code>) und Instanzreferenzen (<code>AnyInstanceRef</code>) im Rahmen des Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert die Klassenstruktur zur logischen Gruppierung von Modellelementen:</p>\n<ul class=\"fig-list\"><li><code>Identifiable</code> (spezialisiert <code>MultilanguageReferrable</code>): Basisklasse mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.\n</li><li><code>CollectableElement</code> (abstrakt): Spezialisiert <code>Identifiable</code>. Dient als Oberklasse für sammelbare Entitäten.\n</li><li><code>PackageableElement</code> (abstrakt): Spezialisiert <code>CollectableElement</code> und <code>Identifiable</code>.\n</li><li><code>ARPackage</code>: Spezialisiert <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Enthält über die Komposition <code>+element 0..*</code> mit Stereotyp <code>«atpSplitable,atpVariation»</code> Elemente des Typs <code>PackageableElement</code>.\n</li><li><code>ARElement</code> (abstrakt): Spezialisiert <code>PackageableElement</code>.\n</li><li><code>Collection</code>: Spezialisiert <code>ARElement</code>. Besitzt die Attribute <code>autoCollect: AutoCollectEnum [0..1]</code> und <code>elementRole: Identifier [0..1]</code>. Assoziiert direkt sammelbare Elemente über <code>+element 0..*</code> zu <code>Identifiable</code> sowie Quellelemente über <code>+sourceElement 0..*</code> zu <code>Identifiable</code>.\n</li><li><code>AutoCollectEnum</code> («enumeration»): Werte <code>refAll</code>, <code>refNonStandard</code>, <code>refNone</code>.\n</li><li><code>AtpFeature</code>: Basisklasse für referenzierbare Features.\n</li><li><code>AtpInstanceRef</code> / <code>AnyInstanceRef</code>: Modellierung generischer Instanzpfade. Besitzt die Referenzen <code>+target: AtpFeature [1]</code> mit <code>{redefines atpTarget}</code> und <code>+contextElement: AtpFeature [0..*]</code> mit <code>{subsets atpContextElement}</code>.\n</li><li>Kompositionen von <code>Collection</code> zu <code>AnyInstanceRef</code>:\n<ul class=\"fig-list\"><li><code>+collectedInstance 0..*</code> (Instanzreferenz-Spezifikation <code>«instanceRef» +collectedInstance 0..*</code> auf <code>AtpFeature</code>)\n</li><li><code>+sourceInstance 0..*</code> (Instanzreferenz-Spezifikation <code>«instanceRef» +sourceInstance 0..*</code> auf <code>AtpFeature</code>)\n</li></ul>\n</li><li><code>EvaluatedVariantSet</code>: Spezialisiert <code>ARElement</code> mit Attribut <code>approvalStatus: NameToken</code>. Assoziiert ausgewertete Elemente über <code>+evaluatedElement 0..*</code> zu <code>CollectableElement</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen oder Zustandsübergänge. Die Beziehungen definieren die Deklarationshierarchie sowie Mechanismen zur Auflösung von Instanzreferenzen über Kontextelemente hinweg zum Zielobjekt (<code>target</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Collection</code> erlaubt sowohl die direkte Adressierung von Metamodellelementen (<code>Identifiable</code>) über <code>element</code> und <code>sourceElement</code> als auch die instanzbasierte Adressierung über <code>AnyInstanceRef</code> (<code>collectedInstance</code>, <code>sourceInstance</code>).\n</li><li>Bei Verwendung von <code>AnyInstanceRef</code> muss genau ein Ziel (<code>target: 1</code>) referenziert werden; hierarchische Kontexte werden über <code>contextElement [0..*]</code> aufgespannt.\n</li><li>Das Attribut <code>autoCollect</code> steuert automatische Einschlussmechanismen über die Aufzählungswerte von <code>AutoCollectEnum</code>.\n</li><li>Die Assoziation <code>ARPackage.element</code> unterliegt den Mechanismen von Variabilität und Aufspaltbarkeit (<code>«atpSplitable,atpVariation»</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4ee01e1376b34405", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-Metamodell-Struktur für Sammlungen (<code>Collection</code>) und Instanzreferenzen (<code>AnyInstanceRef</code>) im Rahmen des Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert die Klassenstruktur zur logischen Gruppierung von Modellelementen:</p>\n<ul class=\"fig-list\"><li><code>Identifiable</code> (spezialisiert <code>MultilanguageReferrable</code>): Basisklasse mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.\n</li><li><code>CollectableElement</code> (abstrakt): Spezialisiert <code>Identifiable</code>. Dient als Oberklasse für sammelbare Entitäten.\n</li><li><code>PackageableElement</code> (abstrakt): Spezialisiert <code>CollectableElement</code> und <code>Identifiable</code>.\n</li><li><code>ARPackage</code>: Spezialisiert <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Enthält über die Komposition <code>+element 0..*</code> mit Stereotyp <code>«atpSplitable,atpVariation»</code> Elemente des Typs <code>PackageableElement</code>.\n</li><li><code>ARElement</code> (abstrakt): Spezialisiert <code>PackageableElement</code>.\n</li><li><code>Collection</code>: Spezialisiert <code>ARElement</code>. Besitzt die Attribute <code>autoCollect: AutoCollectEnum [0..1]</code> und <code>elementRole: Identifier [0..1]</code>. Assoziiert direkt sammelbare Elemente über <code>+element 0..*</code> zu <code>Identifiable</code> sowie Quellelemente über <code>+sourceElement 0..*</code> zu <code>Identifiable</code>.\n</li><li><code>AutoCollectEnum</code> («enumeration»): Werte <code>refAll</code>, <code>refNonStandard</code>, <code>refNone</code>.\n</li><li><code>AtpFeature</code>: Basisklasse für referenzierbare Features.\n</li><li><code>AtpInstanceRef</code> / <code>AnyInstanceRef</code>: Modellierung generischer Instanzpfade. Besitzt die Referenzen <code>+target: AtpFeature [1]</code> mit <code>{redefines atpTarget}</code> und <code>+contextElement: AtpFeature [0..*]</code> mit <code>{subsets atpContextElement}</code>.\n</li><li>Kompositionen von <code>Collection</code> zu <code>AnyInstanceRef</code>:\n<ul class=\"fig-list\"><li><code>+collectedInstance 0..*</code> (Instanzreferenz-Spezifikation <code>«instanceRef» +collectedInstance 0..*</code> auf <code>AtpFeature</code>)\n</li><li><code>+sourceInstance 0..*</code> (Instanzreferenz-Spezifikation <code>«instanceRef» +sourceInstance 0..*</code> auf <code>AtpFeature</code>)\n</li></ul>\n</li><li><code>EvaluatedVariantSet</code>: Spezialisiert <code>ARElement</code> mit Attribut <code>approvalStatus: NameToken</code>. Assoziiert ausgewertete Elemente über <code>+evaluatedElement 0..*</code> zu <code>CollectableElement</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen oder Zustandsübergänge. Die Beziehungen definieren die Deklarationshierarchie sowie Mechanismen zur Auflösung von Instanzreferenzen über Kontextelemente hinweg zum Zielobjekt (<code>target</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Collection</code> erlaubt sowohl die direkte Adressierung von Metamodellelementen (<code>Identifiable</code>) über <code>element</code> und <code>sourceElement</code> als auch die instanzbasierte Adressierung über <code>AnyInstanceRef</code> (<code>collectedInstance</code>, <code>sourceInstance</code>).\n</li><li>Bei Verwendung von <code>AnyInstanceRef</code> muss genau ein Ziel (<code>target: 1</code>) referenziert werden; hierarchische Kontexte werden über <code>contextElement [0..*]</code> aufgespannt.\n</li><li>Das Attribut <code>autoCollect</code> steuert automatische Einschlussmechanismen über die Aufzählungswerte von <code>AutoCollectEnum</code>.\n</li><li>Die Assoziation <code>ARPackage.element</code> unterliegt den Mechanismen von Variabilität und Aufspaltbarkeit (<code>«atpSplitable,atpVariation»</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9b5c3a3c3b78e608", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-Metamodell-Struktur für Sammlungen (<code>Collection</code>) und Instanzreferenzen (<code>AnyInstanceRef</code>) im Rahmen des Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert die Klassenstruktur zur logischen Gruppierung von Modellelementen:</p>\n<ul class=\"fig-list\"><li><code>Identifiable</code> (spezialisiert <code>MultilanguageReferrable</code>): Basisklasse mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.\n</li><li><code>CollectableElement</code> (abstrakt): Spezialisiert <code>Identifiable</code>. Dient als Oberklasse für sammelbare Entitäten.\n</li><li><code>PackageableElement</code> (abstrakt): Spezialisiert <code>CollectableElement</code> und <code>Identifiable</code>.\n</li><li><code>ARPackage</code>: Spezialisiert <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Enthält über die Komposition <code>+element 0..*</code> mit Stereotyp <code>«atpSplitable,atpVariation»</code> Elemente des Typs <code>PackageableElement</code>.\n</li><li><code>ARElement</code> (abstrakt): Spezialisiert <code>PackageableElement</code>.\n</li><li><code>Collection</code>: Spezialisiert <code>ARElement</code>. Besitzt die Attribute <code>autoCollect: AutoCollectEnum [0..1]</code> und <code>elementRole: Identifier [0..1]</code>. Assoziiert direkt sammelbare Elemente über <code>+element 0..*</code> zu <code>Identifiable</code> sowie Quellelemente über <code>+sourceElement 0..*</code> zu <code>Identifiable</code>.\n</li><li><code>AutoCollectEnum</code> («enumeration»): Werte <code>refAll</code>, <code>refNonStandard</code>, <code>refNone</code>.\n</li><li><code>AtpFeature</code>: Basisklasse für referenzierbare Features.\n</li><li><code>AtpInstanceRef</code> / <code>AnyInstanceRef</code>: Modellierung generischer Instanzpfade. Besitzt die Referenzen <code>+target: AtpFeature [1]</code> mit <code>{redefines atpTarget}</code> und <code>+contextElement: AtpFeature [0..*]</code> mit <code>{subsets atpContextElement}</code>.\n</li><li>Kompositionen von <code>Collection</code> zu <code>AnyInstanceRef</code>:\n<ul class=\"fig-list\"><li><code>+collectedInstance 0..*</code> (Instanzreferenz-Spezifikation <code>«instanceRef» +collectedInstance 0..*</code> auf <code>AtpFeature</code>)\n</li><li><code>+sourceInstance 0..*</code> (Instanzreferenz-Spezifikation <code>«instanceRef» +sourceInstance 0..*</code> auf <code>AtpFeature</code>)\n</li></ul>\n</li><li><code>EvaluatedVariantSet</code>: Spezialisiert <code>ARElement</code> mit Attribut <code>approvalStatus: NameToken</code>. Assoziiert ausgewertete Elemente über <code>+evaluatedElement 0..*</code> zu <code>CollectableElement</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen oder Zustandsübergänge. Die Beziehungen definieren die Deklarationshierarchie sowie Mechanismen zur Auflösung von Instanzreferenzen über Kontextelemente hinweg zum Zielobjekt (<code>target</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Collection</code> erlaubt sowohl die direkte Adressierung von Metamodellelementen (<code>Identifiable</code>) über <code>element</code> und <code>sourceElement</code> als auch die instanzbasierte Adressierung über <code>AnyInstanceRef</code> (<code>collectedInstance</code>, <code>sourceInstance</code>).\n</li><li>Bei Verwendung von <code>AnyInstanceRef</code> muss genau ein Ziel (<code>target: 1</code>) referenziert werden; hierarchische Kontexte werden über <code>contextElement [0..*]</code> aufgespannt.\n</li><li>Das Attribut <code>autoCollect</code> steuert automatische Einschlussmechanismen über die Aufzählungswerte von <code>AutoCollectEnum</code>.\n</li><li>Die Assoziation <code>ARPackage.element</code> unterliegt den Mechanismen von Variabilität und Aufspaltbarkeit (<code>«atpSplitable,atpVariation»</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-af4cb10925b64dfe", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der AUTOSAR-Metamodell-Struktur für Sammlungen (<code>Collection</code>) und Instanzreferenzen (<code>AnyInstanceRef</code>) im Rahmen des Generic Structure Template (AUTOSAR_TPS_GenericStructureTemplate).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Metamodell definiert die Klassenstruktur zur logischen Gruppierung von Modellelementen:</p>\n<ul class=\"fig-list\"><li><code>Identifiable</code> (spezialisiert <code>MultilanguageReferrable</code>): Basisklasse mit Attributen <code>category: CategoryString [0..1]</code> und <code>uuid: String [0..1]</code>.\n</li><li><code>CollectableElement</code> (abstrakt): Spezialisiert <code>Identifiable</code>. Dient als Oberklasse für sammelbare Entitäten.\n</li><li><code>PackageableElement</code> (abstrakt): Spezialisiert <code>CollectableElement</code> und <code>Identifiable</code>.\n</li><li><code>ARPackage</code>: Spezialisiert <code>AtpBlueprint</code> und <code>AtpBlueprintable</code>. Enthält über die Komposition <code>+element 0..*</code> mit Stereotyp <code>«atpSplitable,atpVariation»</code> Elemente des Typs <code>PackageableElement</code>.\n</li><li><code>ARElement</code> (abstrakt): Spezialisiert <code>PackageableElement</code>.\n</li><li><code>Collection</code>: Spezialisiert <code>ARElement</code>. Besitzt die Attribute <code>autoCollect: AutoCollectEnum [0..1]</code>, <code>collectionSemantics: NameToken [0..1]</code> und <code>elementRole: Identifier [0..1]</code>. Assoziiert direkt sammelbare Elemente über <code>+element 0..*</code> zu <code>Identifiable</code> sowie Quellelemente über <code>+sourceElement 0..*</code> zu <code>Identifiable</code>.\n</li><li><code>AutoCollectEnum</code> («enumeration»): Werte <code>refAll</code>, <code>refNonStandard</code>, <code>refNone</code>.\n</li><li><code>AtpFeature</code>: Basisklasse für referenzierbare Features.\n</li><li><code>AtpInstanceRef</code> / <code>AnyInstanceRef</code>: Modellierung generischer Instanzpfade. Besitzt die Referenzen <code>+target: AtpFeature [1]</code> mit <code>{redefines atpTarget}</code> und <code>+contextElement: AtpFeature [0..*]</code> mit <code>{ordered, subsets atpContextElement}</code>.\n</li><li>Kompositionen von <code>Collection</code> zu <code>AnyInstanceRef</code>:\n<ul class=\"fig-list\"><li><code>+collectedInstance 0..*</code> (Instanzreferenz-Spezifikation <code>«instanceRef» +collectedInstance 0..*</code> auf <code>AtpFeature</code>)\n</li><li><code>+sourceInstance 0..*</code> (Instanzreferenz-Spezifikation <code>«instanceRef» +sourceInstance 0..*</code> auf <code>AtpFeature</code>)\n</li></ul>\n</li><li><code>EvaluatedVariantSet</code>: Spezialisiert <code>ARElement</code> mit Attribut <code>approvalStatus: NameToken</code>. Assoziiert ausgewertete Elemente über <code>+evaluatedElement 0..*</code> zu <code>CollectableElement</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturdiagramm ohne Laufzeitsequenzen oder Zustandsübergänge. Die Beziehungen definieren die Deklarationshierarchie sowie Mechanismen zur Auflösung von Instanzreferenzen über Kontextelemente hinweg zum Zielobjekt (<code>target</code>).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><code>Collection</code> erlaubt sowohl die direkte Adressierung von Metamodellelementen (<code>Identifiable</code>) über <code>element</code> und <code>sourceElement</code> als auch die instanzbasierte Adressierung über <code>AnyInstanceRef</code> (<code>collectedInstance</code>, <code>sourceInstance</code>).\n</li><li>Über <code>collectionSemantics: NameToken [0..1]</code> kann die semantische Bedeutung der Sammlung genauer spezifiziert werden.\n</li><li>Bei Verwendung von <code>AnyInstanceRef</code> muss genau ein Ziel (<code>target: 1</code>) referenziert werden; hierarchische Kontexte werden über die geordnete Liste <code>contextElement [0..*]</code> (<code>{ordered, subsets atpContextElement}</code>) strukturiert.\n</li><li>Das Attribut <code>autoCollect</code> steuert automatische Einschlussmechanismen über die Aufzählungswerte von <code>AutoCollectEnum</code>.\n</li><li>Die Assoziation <code>ARPackage.element</code> unterliegt den Mechanismen von Variabilität und Aufspaltbarkeit (<code>«atpSplitable,atpVariation»</code>).\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-5143caa57a238996", "to": "FIG-d401b1d18f6322b8", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-d401b1d18f6322b8", "to": "FIG-4ee01e1376b34405", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4ee01e1376b34405", "to": "FIG-9b5c3a3c3b78e608", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Identifiable, Collection: Typannotationen vereinheitlicht (Leerzeichen vor dem Doppelpunkt entfernt, z. B. <code>category: CategoryString</code> statt <code>category :CategoryString</code>).\n</li><li>Collection: Leerraum vor <code>: AutoCollectEnum</code> und <code>: Identifier</code> typografisch bereinigt.\n</li></ul>"}, {"from": "FIG-9b5c3a3c3b78e608", "to": "FIG-af4cb10925b64dfe", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Collection: Attribut <code>collectionSemantics: NameToken [0..1]</code> hinzugefügt.\n</li><li>AnyInstanceRef: Rolle <code>contextElement</code> um die Eigenschaft <code>{ordered}</code> erweitert (<code>{ordered, subsets atpContextElement}</code>).\n</li></ul>"}]};
